package org.example.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.net.URI; import java.net.http.*;
@Service public class CashfreePaymentService {
 @Value("${cashfree.app-id}") private String appId; @Value("${cashfree.secret-key}") private String secretKey; @Value("${cashfree.api-url}") private String apiUrl; @Value("${cashfree.api-version}") private String apiVersion;
 public String createOrder(String orderId,double amount,String name,String phone,String returnUrl){try{String body="{\"order_id\":\""+orderId+"\",\"order_amount\":"+String.format(java.util.Locale.US,"%.2f",amount)+",\"order_currency\":\"INR\",\"customer_details\":{\"customer_id\":\""+orderId+"\",\"customer_name\":\""+name+"\",\"customer_phone\":\""+phone+"\"},\"order_meta\":{\"return_url\":\""+returnUrl+"\"}}";HttpRequest q=HttpRequest.newBuilder().uri(URI.create(apiUrl+"/orders")).header("Content-Type","application/json").header("x-api-version",apiVersion).header("x-client-id",appId).header("x-client-secret",secretKey).POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String> r=HttpClient.newHttpClient().send(q,HttpResponse.BodyHandlers.ofString());if(r.statusCode()>=200&&r.statusCode()<300)return r.body();throw new RuntimeException("Cashfree API Error: "+r.body());}catch(Exception e){throw new RuntimeException("Cashfree payment creation failed",e);}}
}
